DEFAULT_REPO = "gkeyllorg/gkeyll"
MARKER_FORMAT = '<!-- gkeyll-ci-report context="{}" -->'
COMMENT_LIMIT = 60000  # UTF-8 bytes; leave room for run metadata and navigation.
RUN_MARKER = '<!-- gkeyll-ci-run {} -->'


# ---- helpers ---------------------------------------------------------------

def read_text(path):
    try:
